(function(e){e.JobLabContent=Object.assign(e.JobLabContent||{},{"KK-030":{scenario:{company:"Quarry Lane Software",supervisor:{name:"Khúc Thị Lan Phương",role:{vi:"Trưởng nhóm Đảm bảo Chất lượng",en:"QA Lead"}},ref_code:"TR-0817",title:{vi:"Phân loại lỗi đúng mức. Tính tỷ lệ đúng mẫu số.",en:"Rate defects honestly. Use the right denominator."},brief:{vi:"Bạn tổng hợp báo cáo kết thúc kiểm thử TR-0817 cho bản phát hành cổng thanh toán. Kế hoạch có 420 ca; đã thực thi 400 ca (386 đạt, 14 lỗi), 20 ca chưa chạy do môi trường bị chặn. Lỗi BUG-5521 làm trừ tiền hai lần khi người dùng bấm thanh toán lại lúc mạng chậm. Đối chiếu báo cáo nháp với tiêu chí kết thúc đã duyệt, sửa mức nghiêm trọng của BUG-5521 và tỷ lệ đạt, rồi lập báo cáo có căn cứ.",en:"You are compiling the test completion report TR-0817 for a payment gateway release. The plan has 420 cases; 400 were executed (386 passed, 14 failed) and 20 were not run because the environment was blocked. BUG-5521 charges users twice when they tap pay again on a slow network. Compare the draft with the approved exit criteria, fix the BUG-5521 severity and the pass rate, then write an evidence-based report."},reference_title:{vi:"Tiêu chí kết thúc kiểm thử đã duyệt · TR-0817",en:"Approved test exit criteria · TR-0817"},fields:[{id:"SEVERITY",label:{vi:"Mức nghiêm trọng BUG-5521",en:"BUG-5521 severity"},initial:"S3-Minor",expected:"S1-Critical",choices:["S3-Minor","S2-Major","S1-Critical"],reference:"Ma trận mức độ nghiêm trọng",hint:{vi:"Lỗi gây sai lệch tiền hoặc mất dữ liệu của khách hàng xếp mức cao nhất, kể cả khi có cách né tạm thời.",en:"Defects that misstate customer money or lose data get the top level, even when a workaround exists."}},{id:"PASS_RATE",label:{vi:"Tỷ lệ đạt (%)",en:"Pass rate (%)"},initial:"91.9",expected:"96.5",reference:"Tiêu chí kết thúc kiểm thử",ref_value:{vi:"Đã thực thi 400 ca: 386 đạt, 14 lỗi; 20 ca chưa chạy; làm tròn 1 chữ số thập phân",en:"400 cases executed: 386 passed, 14 failed; 20 not run; round to 1 decimal place"},hint:{vi:"Mẫu số của tỷ lệ đạt là số ca đã thực thi; ca chưa chạy được báo cáo riêng.",en:"The pass rate denominator is executed cases; not-run cases are reported separately."}}],sop32:{vi:"Tỷ lệ đạt = số ca đạt / số ca đã thực thi x 100, làm tròn 1 chữ số thập phân; ca chưa chạy báo cáo riêng. Điều kiện GO: tỷ lệ đạt từ 95% và không còn lỗi S1 mở.",en:"Pass rate = passed cases / executed cases x 100, rounded to 1 decimal; not-run cases are reported separately. GO requires a pass rate of at least 95% and no open S1 defect."},context:{label:"TEST MANAGEMENT / TR-0817",metrics:[{label:{vi:"Ca theo kế hoạch",en:"Planned cases"},value:"420"},{label:{vi:"Ca đã thực thi",en:"Executed cases"},value:"400"},{label:{vi:"Lỗi đang mở",en:"Open defects"},value:"14"}]},crisis:{vi:"Giám đốc dự án nhắn: “Hạ BUG-5521 xuống Minor và tạm tắt 14 ca lỗi trong bộ hồi quy cho pipeline xanh. Khách đã chốt go-live sáng mai, sửa sau cũng được.”",en:"The project director messages you: “Downgrade BUG-5521 to Minor and disable the 14 failing regression cases so the pipeline turns green. The client confirmed go-live tomorrow morning, we can fix it later.”"},options:{safe:{vi:"Giữ mức S1 và kết quả thật, báo trưởng nhóm QA và hội đồng phát hành, khuyến nghị NO-GO hoặc go-live sau khi có bản vá đã kiểm thử lại.",en:"Keep S1 and the real results, report to the QA lead and release board, and recommend NO-GO or go-live only after a retested fix."},shortcut:{vi:"Hạ mức lỗi, tắt các ca lỗi để pipeline xanh và ghi chú sẽ sửa ở bản sau.",en:"Downgrade the defect, disable the failing cases for a green pipeline and note it for the next release."},wait:{vi:"Không cập nhật báo cáo và chờ giám đốc dự án tự quyết định go-live.",en:"Leave the report as is and wait for the project director to decide on go-live."}},questions:{vi:["Vì sao BUG-5521 phải là S1-Critical và tỷ lệ đạt đúng là 96.5%? Kết luận GO hay NO-GO, căn cứ dòng nào?","Nếu bị yêu cầu tắt ca kiểm thử lỗi để kịp go-live, bạn bảo vệ tính toàn vẹn của kết quả kiểm thử thế nào?"],en:["Why must BUG-5521 be S1-Critical and the pass rate 96.5%? Is the verdict GO or NO-GO, based on which lines?","If you are asked to disable failing tests to meet go-live, how do you protect the integrity of the test results?"]},hints:{vi:["Đọc mô tả lỗi và ma trận mức độ nghiêm trọng trước, đừng dựa vào việc có cách né hay không.","Xác định đúng tử số và mẫu số theo SOP mục 3.2 trước khi chia.","Đọc lại SOP mục 4.2: kết quả kiểm thử không được chỉnh để phục vụ lịch go-live; rủi ro phải được báo lên hội đồng phát hành."],en:["Read the defect description and the severity matrix first; do not rely on whether a workaround exists.","Identify the right numerator and denominator per SOP 3.2 before dividing.","Re-read SOP 4.2: test results are never adjusted to fit a go-live date; risks go to the release board."]},terminal:{system:"qa-runner",settable:["SEVERITY","PASS_RATE"],commands:[{cmd:"status",out:{vi:"Lượt chạy TR-0817: 400/420 ca đã thực thi | 386 PASS | 14 FAIL | 20 NOT RUN (sandbox thanh toán bị chặn).",en:"Run TR-0817: 400/420 cases executed | 386 PASS | 14 FAIL | 20 NOT RUN (payment sandbox blocked)."}},{cmd:"cat bug-5521.md",out:{vi:"Bấm Thanh toán lần hai khi mạng chậm: tạo 2 giao dịch, trừ tiền 2 lần. Cách né: chờ 30 giây. Ảnh hưởng: sai lệch tiền của khách.",en:"Tapping Pay twice on a slow network creates 2 transactions and charges twice. Workaround: wait 30 seconds. Impact: customer money misstated."}},{cmd:"cat severity_matrix.md",out:{vi:"S1: sai lệch tiền, mất dữ liệu, lỗ hổng bảo mật (kể cả khi có cách né) | S2: chức năng chính lỗi, có cách né | S3: lỗi giao diện nhỏ.",en:"S1: money misstated, data loss, security hole (even with a workaround) | S2: main function broken, workaround exists | S3: minor UI issue."}},{cmd:"cat exit_criteria.md",out:{vi:"GO khi tỷ lệ đạt (trên số ca đã thực thi) từ 95% và 0 lỗi S1 mở; ca NOT RUN phải có kế hoạch chạy bù.",en:"GO when the pass rate (over executed cases) is at least 95% and 0 S1 defects are open; NOT RUN cases need a catch-up plan."}},{cmd:"pytest --last-failed",out:{vi:"14 failed: 9 ca thanh toán lặp, 3 ca hoàn tiền, 2 ca giao diện; chạy lại 3 lần vẫn lỗi, không phải ca flaky.",en:"14 failed: 9 duplicate payment cases, 3 refund cases, 2 UI cases; still failing after 3 reruns, not flaky."}}]}},learning:{summary:{vi:"Kỹ sư kiểm thử phần mềm thủ công và tự động thiết kế chiến lược, ca kiểm thử và bộ kiểm thử tự động để phát hiện lỗi sớm, đo chất lượng và đưa ra khuyến nghị phát hành dựa trên bằng chứng. Họ kết hợp kỹ thuật thiết kế ca kiểm thử, tự động hóa giao diện và API, kiểm thử hiệu năng và quản lý lỗi. Giá trị cốt lõi là thông tin trung thực về rủi ro chất lượng cho người ra quyết định.",en:"A manual and automation QA engineer designs the test strategy, test cases and automated suites to find defects early, measure quality and make evidence-based release recommendations. The role combines test design techniques, UI and API automation, performance testing and defect management. Its core value is honest information about quality risk for decision makers."},responsibilities:{vi:["Phân tích yêu cầu, nhận diện rủi ro và lập kế hoạch, chiến lược kiểm thử.","Thiết kế ca kiểm thử bằng phân vùng tương đương, giá trị biên, bảng quyết định, chuyển trạng thái.","Xây dựng và bảo trì bộ kiểm thử tự động giao diện, API và tích hợp vào CI/CD.","Ghi nhận lỗi, phân loại mức nghiêm trọng, theo dõi vòng đời lỗi, kiểm thử lại và hồi quy.","Báo cáo kết quả, đánh giá tiêu chí kết thúc và khuyến nghị GO/NO-GO."],en:["Analyse requirements, identify risks and plan the test strategy.","Design test cases with equivalence partitioning, boundary values, decision tables and state transitions.","Build and maintain automated UI and API suites integrated into CI/CD.","Log defects, rate severity, track the defect lifecycle, retest and run regression.","Report results, evaluate exit criteria and recommend GO/NO-GO."]},competencies:[{name:{vi:"Thiết kế ca kiểm thử",en:"Test design"},desc:{vi:"Chọn kỹ thuật phù hợp để phủ rủi ro cao với số ca tối thiểu, có truy vết tới yêu cầu.",en:"Pick the right techniques to cover high risks with minimal cases, traced to requirements."}},{name:{vi:"Tự động hóa kiểm thử",en:"Test automation"},desc:{vi:"Viết kịch bản ổn định (Page Object, selector bền, dữ liệu độc lập) và giảm ca flaky.",en:"Write stable scripts (Page Object, robust selectors, independent data) and reduce flaky tests."}},{name:{vi:"Kiểm thử API & hiệu năng",en:"API & performance testing"},desc:{vi:"Kiểm tra hợp đồng API, mã lỗi, tính lũy đẳng; đo độ trễ và thông lượng dưới tải.",en:"Check API contracts, error codes and idempotency; measure latency and throughput under load."}},{name:{vi:"Phân tích lỗi",en:"Defect analysis"},desc:{vi:"Tái hiện, khoanh vùng và mô tả lỗi rõ ràng để lập trình viên sửa nhanh.",en:"Reproduce, isolate and describe defects clearly so developers can fix them fast."}},{name:{vi:"Trung thực & độc lập",en:"Integrity & independence"},desc:{vi:"Báo cáo đúng kết quả dù chịu áp lực tiến độ; không che giấu hay hạ mức lỗi.",en:"Report true results under schedule pressure; never hide or downgrade defects."}}],knowledge:{vi:["ISTQB Foundation Level: 7 nguyên tắc kiểm thử, cấp độ và loại kiểm thử, kỹ thuật hộp đen và hộp trắng.","ISO/IEC/IEEE 29119 về quy trình, tài liệu và kỹ thuật kiểm thử phần mềm.","ISO/IEC 25010: mô hình chất lượng sản phẩm phần mềm (tính phù hợp chức năng, hiệu năng, bảo mật...).","Kim tự tháp kiểm thử, shift-left và kiểm thử liên tục trong CI/CD.","Phân biệt mức nghiêm trọng (severity) và độ ưu tiên (priority); tiêu chí vào và kết thúc kiểm thử."],en:["ISTQB Foundation Level: 7 testing principles, test levels and types, black-box and white-box techniques.","ISO/IEC/IEEE 29119 on software testing processes, documentation and techniques.","ISO/IEC 25010: software product quality model (functional suitability, performance, security...).","The test pyramid, shift-left and continuous testing in CI/CD.","Severity versus priority; entry and exit criteria for testing."]},tools:["Playwright / Selenium","Postman","k6","Công cụ quản lý ca kiểm thử","Git & CI runner"],kpis:{vi:["Tỷ lệ lỗi lọt ra môi trường production (defect leakage).","Độ bao phủ yêu cầu bởi ca kiểm thử.","Tỷ lệ ca tự động flaky trong bộ hồi quy.","Thời gian chạy bộ hồi quy trong pipeline."],en:["Defect leakage to production.","Requirement coverage by test cases.","Flaky test rate in the regression suite.","Regression suite run time in the pipeline."]},day:[{time:"08:30",vi:"Xem kết quả bộ hồi quy chạy đêm, tách lỗi thật khỏi lỗi môi trường.",en:"Review the nightly regression run and separate real failures from environment issues."},{time:"09:30",vi:"Họp sprint, làm rõ tiêu chí chấp nhận của các user story mới.",en:"Join the sprint meeting and clarify acceptance criteria of new user stories."},{time:"10:30",vi:"Thiết kế ca kiểm thử giá trị biên cho chức năng hoàn tiền.",en:"Design boundary value cases for the refund feature."},{time:"14:00",vi:"Viết kịch bản tự động API thanh toán, kiểm tra tính lũy đẳng khi gửi lặp.",en:"Automate payment API tests, checking idempotency on repeated requests."},{time:"16:30",vi:"Cập nhật báo cáo kiểm thử, phân loại lỗi mới và gửi khuyến nghị cho trưởng nhóm.",en:"Update the test report, triage new defects and send recommendations to the lead."}],mistakes:{vi:["Tính tỷ lệ đạt trên số ca kế hoạch hoặc gộp ca chưa chạy vào ca lỗi.","Hạ mức nghiêm trọng vì có cách né dù lỗi gây sai lệch tiền hoặc dữ liệu.","Tắt, xóa ca kiểm thử lỗi để pipeline xanh thay vì tìm nguyên nhân gốc."],en:["Computing the pass rate over planned cases or counting not-run cases as failures.","Downgrading severity because a workaround exists although money or data is affected.","Disabling or deleting failing tests to get a green pipeline instead of finding the root cause."]},career:[{vi:"Kiểm thử viên tập sự",en:"Junior tester"},{vi:"Kỹ sư kiểm thử",en:"QA engineer"},{vi:"Kỹ sư kiểm thử tự động cấp cao / trưởng nhóm QA",en:"Senior automation engineer / QA lead"},{vi:"Quản lý kiểm thử / quản lý chất lượng phần mềm",en:"Test manager / software quality manager"}],glossary:[{term:"Severity",vi:"Mức độ ảnh hưởng của lỗi tới hệ thống và người dùng, do QA đánh giá theo ma trận.",en:"How badly a defect affects the system and users, rated by QA against a matrix."},{term:"Priority",vi:"Mức độ cần sửa sớm của lỗi theo nhu cầu kinh doanh, có thể khác mức nghiêm trọng.",en:"How soon a defect must be fixed for business needs, which can differ from severity."},{term:"Regression test",vi:"Kiểm thử lại các chức năng cũ để chắc thay đổi mới không làm hỏng chúng.",en:"Re-testing existing features to make sure new changes did not break them."},{term:"Flaky test",vi:"Ca kiểm thử lúc đạt lúc lỗi mà mã không đổi, thường do thời gian chờ hoặc dữ liệu dùng chung.",en:"A test that passes and fails without code changes, often due to timing or shared data."},{term:"Exit criteria",vi:"Điều kiện đã thống nhất để kết thúc kiểm thử và ra quyết định phát hành.",en:"Agreed conditions for ending testing and making the release decision."}],quiz:[{q:{vi:"Trường tuổi hợp lệ từ 18 đến 60. Theo phân tích giá trị biên hai điểm, cần kiểm thử những giá trị nào?",en:"A valid age field ranges from 18 to 60. With two-value boundary analysis, which values should you test?"},options:{vi:["18 và 60","17, 18, 60, 61","18, 39, 60","0, 18, 60, 100"],en:["18 and 60","17, 18, 60, 61","18, 39, 60","0, 18, 60, 100"]},answer:1,explain:{vi:"Mỗi biên gồm giá trị biên và giá trị liền kề ở phân vùng không hợp lệ: 17, 18, 60, 61.",en:"Each boundary takes the boundary value and its neighbour in the invalid partition: 17, 18, 60, 61."}},{q:{vi:"Đã thực thi 250 ca: 235 đạt, 15 lỗi; còn 30 ca chưa chạy. Tỷ lệ đạt là bao nhiêu?",en:"250 cases executed: 235 passed, 15 failed; 30 not run. What is the pass rate?"},options:{vi:["83.9%","90.0%","94.0%","100%"],en:["83.9%","90.0%","94.0%","100%"]},answer:2,explain:{vi:"235 / 250 x 100 = 94.0%; 30 ca chưa chạy được báo cáo riêng, không đưa vào mẫu số.",en:"235 / 250 x 100 = 94.0%; the 30 not-run cases are reported separately, not in the denominator."}},{q:{vi:"Cấp trên yêu cầu tắt các ca kiểm thử lỗi để pipeline xanh trước go-live. Bạn làm gì?",en:"A manager asks you to disable failing tests so the pipeline is green before go-live. What do you do?"},options:{vi:["Giữ kết quả thật, báo trưởng nhóm QA và hội đồng phát hành kèm đánh giá rủi ro","Tắt ca lỗi vì quyết định thuộc về cấp trên","Xóa ca lỗi và viết lại sau go-live","Im lặng và để lập trình viên tự xử lý"],en:["Keep the real results and report to the QA lead and release board with a risk assessment","Disable them because the decision belongs to the manager","Delete the failing tests and rewrite them after go-live","Stay silent and let developers handle it"]},answer:0,explain:{vi:"Kết quả kiểm thử phải trung thực; quyết định chấp nhận rủi ro thuộc hội đồng phát hành dựa trên thông tin đầy đủ.",en:"Test results must be honest; accepting risk is the release board's decision based on full information."}},{q:{vi:"Logo sai màu trên trang chủ ngay trước buổi ra mắt lớn thường được xếp thế nào?",en:"A wrong logo colour on the home page right before a major launch is usually rated how?"},options:{vi:["Nghiêm trọng cao, ưu tiên thấp","Nghiêm trọng cao, ưu tiên cao","Nghiêm trọng thấp, ưu tiên thấp","Nghiêm trọng thấp, ưu tiên cao"],en:["High severity, low priority","High severity, high priority","Low severity, low priority","Low severity, high priority"]},answer:3,explain:{vi:"Lỗi không ảnh hưởng chức năng (nghiêm trọng thấp) nhưng cần sửa gấp vì hình ảnh thương hiệu (ưu tiên cao).",en:"It does not affect functionality (low severity) but must be fixed fast for brand image (high priority)."}}],tools_en:["Playwright / Selenium","Postman","k6","Test case management tool","Git & CI runner"]}}})})(window.KKR);
